with cleaned as (select *, substring(product_name, 1, 4) product_name_prefix, coalesce(brand, 'DIRECT') resolved_brand from products where launch_date >= date '2024-04-24' and supplier_id is not null) select *, last_value(stock_qty) ignore nulls over (partition by category order by launch_date, id rows between unbounded preceding and current row) last_known_stock_qty, sum(price) over (partition by brand order by stock_qty, id rows between unbounded preceding and current row) cumulative_price from cleaned;
